{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_CATEGORY_TARGET_ACHIEVEMENT AS WITH FY_MONTHS_GENERATOR AS ( SELECT SEQ.SEQ AS MONTH_OFFSET, TO_CHAR(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'YYYY-MM\') AS REPORT_MONTH, TO_CHAR(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'Mon YYYY\') AS MONTH_LABEL, DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())) AS START_DATE, CASE WHEN SEQ.SEQ = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END AS END_DATE FROM ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS SEQ FROM TABLE(GENERATOR(ROWCOUNT => 24)) ) SEQ WHERE DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())) >= DATE_TRUNC(\'YEAR\', DATEADD(\'MONTH\', -9, CURRENT_DATE())) ), LATEST_INV_DATES AS ( SELECT P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, COALESCE(MAX(I.DATE), P.END_DATE) AS MAX_INV_DATE FROM FY_MONTHS_GENERATOR P LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I ON I.DATE <= P.END_DATE GROUP BY P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, P.MONTH_OFFSET ), STORE_MONTHLY_TARGETS_RAW AS ( SELECT CAST(TRIM(BRANCH_CODE) AS VARCHAR) AS BRANCH_CODE, TO_CHAR( COALESCE( TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\') ), \'YYYY-MM\' ) AS REPORT_MONTH, AVG(CAST(REGEXP_REPLACE(TRIM(CUMULATIVE_TARGET_MTD), \'[^0-9.]\', \'\') AS NUMBER(18,2))) AS STORE_TARGET FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_CLEAN WHERE TARGET_MONTH IS NOT NULL AND CUMULATIVE_TARGET_MTD IS NOT NULL GROUP BY CAST(TRIM(BRANCH_CODE) AS VARCHAR), TO_CHAR(COALESCE(TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\')), \'YYYY-MM\') ), HIERARCHY_TARGETS AS ( SELECT \'3. Store Wise\' AS HIERARCHY_LEVEL, S.BRANCH_CODE AS LOCATION_ID, S.REPORT_MONTH, S.STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S UNION ALL SELECT \'2. Cluster Wise\' AS HIERARCHY_LEVEL, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS LOCATION_ID, S.REPORT_MONTH, SUM(S.STORE_TARGET) AS STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON S.BRANCH_CODE = CAST(M.BRANCH_CODE AS VARCHAR) GROUP BY COALESCE(M.CLUSTER_NAME, \'OTHERS\'), S.REPORT_MONTH UNION ALL SELECT \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, S.REPORT_MONTH, SUM(S.STORE_TARGET) AS STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S GROUP BY S.REPORT_MONTH ), INV_METRICS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS CLUSTER_NAME, COALESCE( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'TSHIRT\', \'T SHIRT\', \'T-SHIRT\', \'T-SHIRTS\', \'POLO\', \'POLOS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'OVERSHIRTS\', \'OVER SHIRT\', \'OVERSHIRT\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SWEAT SHIRT\', \'SWEAT SHIRTS\', \'SWEATSHIRT\', \'SWEATSHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'TRACKPANTS\', \'TRACK PANTS\', \'JOGGER\', \'JOGGERS\', \'JOGGERS & TRACKPANTS\') THEN \'JOGGERS AND TRACKPANTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CARGO\', \'CARGOS\', \'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'COORD\', \'COORDS\', \'CO-ORD\', \'CO-ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BOXER\', \'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BAG\', \'BAGS\', \'BACKPACK\', \'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'PERFUME\', \'PERFUMES\', \'FRAGRANCE\') THEN \'PERFUMES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SUNGLASS\', \'SUNGLASSES\', \'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BELT\', \'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SHOE\', \'SHOES\', \'SNEAKER\', \'SNEAKERS\', \'FOOTWEAR\') THEN \'SHOES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SOCK\', \'SOCKS\', \'ACCESSORY\', \'ACCESSORIES\', \'CAP\', \'CAPS\') THEN \'ACCESSORIES\' WHEN TRIM(I.NEW_CATEGORY) <> \'\' THEN UPPER(TRIM(I.NEW_CATEGORY)) ELSE NULL END, \'OTHERS\' ) AS CATEGORY, SUM(COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_CLOSING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.MAX_INV_DATE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') GROUP BY L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY ), OPENING_INV_METRICS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS CLUSTER_NAME, COALESCE( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'TSHIRT\', \'T SHIRT\', \'T-SHIRT\', \'T-SHIRTS\', \'POLO\', \'POLOS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'OVERSHIRTS\', \'OVER SHIRT\', \'OVERSHIRT\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SWEAT SHIRT\', \'SWEAT SHIRTS\', \'SWEATSHIRT\', \'SWEATSHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'TRACKPANTS\', \'TRACK PANTS\', \'JOGGER\', \'JOGGERS\', \'JOGGERS & TRACKPANTS\') THEN \'JOGGERS AND TRACKPANTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CARGO\', \'CARGOS\', \'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'COORD\', \'COORDS\', \'CO-ORD\', \'CO-ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BOXER\', \'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BAG\', \'BAGS\', \'BACKPACK\', \'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'PERFUME\', \'PERFUMES\', \'FRAGRANCE\') THEN \'PERFUMES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SUNGLASS\', \'SUNGLASSES\', \'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BELT\', \'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SHOE\', \'SHOES\', \'SNEAKER\', \'SNEAKERS\', \'FOOTWEAR\') THEN \'SHOES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SOCK\', \'SOCKS\', \'ACCESSORY\', \'ACCESSORIES\', \'CAP\', \'CAPS\') THEN \'ACCESSORIES\' WHEN TRIM(I.NEW_CATEGORY) <> \'\' THEN UPPER(TRIM(I.NEW_CATEGORY)) ELSE NULL END, \'OTHERS\' ) AS CATEGORY, SUM(COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_OPENING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.START_DATE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') GROUP BY L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY ), SALES_METRICS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, S.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', S.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS CLUSTER_NAME, COALESCE( CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'TSHIRT\', \'T SHIRT\', \'T-SHIRT\', \'T-SHIRTS\', \'POLO\', \'POLOS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'OVERSHIRTS\', \'OVER SHIRT\', \'OVERSHIRT\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'SWEAT SHIRT\', \'SWEAT SHIRTS\', \'SWEATSHIRT\', \'SWEATSHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'TRACKPANTS\', \'TRACK PANTS\', \'JOGGER\', \'JOGGERS\', \'JOGGERS & TRACKPANTS\') THEN \'JOGGERS AND TRACKPANTS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CARGO\', \'CARGOS\', \'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'COORD\', \'COORDS\', \'CO-ORD\', \'CO-ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'BOXER\', \'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'BAG\', \'BAGS\', \'BACKPACK\', \'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'PERFUME\', \'PERFUMES\', \'FRAGRANCE\') THEN \'PERFUMES\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'SUNGLASS\', \'SUNGLASSES\', \'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'BELT\', \'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'SHOE\', \'SHOES\', \'SNEAKER\', \'SNEAKERS\', \'FOOTWEAR\') THEN \'SHOES\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'SOCK\', \'SOCKS\', \'ACCESSORY\', \'ACCESSORIES\', \'CAP\', \'CAPS\') THEN \'ACCESSORIES\' WHEN TRIM(S.CATEGORY) <> \'\' THEN UPPER(TRIM(S.CATEGORY)) ELSE NULL END, \'OTHERS\' ) AS CATEGORY, SUM(S.SHIPPING_QUANTITY) AS SALES_UNITS, SUM(S.SHIPPING_QUANTITY * S.SELLING_PRICE) AS SALES_REVENUE, SUM(S.SHIPPING_QUANTITY * (S.SELLING_PRICE - COALESCE(S.TAX, 0) - COALESCE(S.COGS_PRICE, 0))) AS GROSS_PROFIT FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE S INNER JOIN LATEST_INV_DATES L ON S.ORDER_DATE >= L.START_DATE AND S.ORDER_DATE <= L.END_DATE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(S.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE LOWER(S.ORDER_STATUS) LIKE \'%process%\' AND S.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') AND CAST(S.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') GROUP BY L.REPORT_MONTH, L.MONTH_LABEL, S.BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY ), COMBINED_METRICS AS ( SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, 0 AS INV_UNITS_CLOSING, 0 AS INV_UNITS_OPENING, SALES_UNITS, SALES_REVENUE, GROSS_PROFIT FROM SALES_METRICS UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, INV_UNITS_CLOSING, 0 AS INV_UNITS_OPENING, 0 AS SALES_UNITS, 0 AS SALES_REVENUE, 0 AS GROSS_PROFIT FROM INV_METRICS UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, 0 AS INV_UNITS_CLOSING, INV_UNITS_OPENING, 0 AS SALES_UNITS, 0 AS SALES_REVENUE, 0 AS GROSS_PROFIT FROM OPENING_INV_METRICS ), UNIFIED_AGGREGATE AS ( SELECT REPORT_MONTH, MONTH_LABEL, \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, \'National (All Stores)\' AS LOCATION_NAME, CATEGORY, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_UNITS) AS SALES_UNITS, SUM(SALES_REVENUE) AS SALES_REVENUE, SUM(GROSS_PROFIT) AS GROSS_PROFIT FROM COMBINED_METRICS GROUP BY 1, 2, 3, 4, 5, 6 UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, \'2. Cluster Wise\' AS HIERARCHY_LEVEL, CLUSTER_NAME AS LOCATION_ID, CONCAT(CLUSTER_NAME, \' Cluster\') AS LOCATION_NAME, CATEGORY, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_UNITS) AS SALES_UNITS, SUM(SALES_REVENUE) AS SALES_REVENUE, SUM(GROSS_PROFIT) AS GROSS_PROFIT FROM COMBINED_METRICS GROUP BY 1, 2, 3, 4, 5, 6 UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, \'3. Store Wise\' AS HIERARCHY_LEVEL, CAST(BRANCH_CODE AS VARCHAR) AS LOCATION_ID, STORE_NAME AS LOCATION_NAME, CATEGORY, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_UNITS) AS SALES_UNITS, SUM(SALES_REVENUE) AS SALES_REVENUE, SUM(GROSS_PROFIT) AS GROSS_PROFIT FROM COMBINED_METRICS GROUP BY 1, 2, 3, 4, 5, 6 ), CATEGORY_PERF AS ( SELECT REPORT_MONTH, MONTH_LABEL, HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, STORE_INV_UNITS_CLOSING, STORE_INV_UNITS_OPENING, ROUND(100.0 * STORE_INV_UNITS_CLOSING / NULLIF(SUM(STORE_INV_UNITS_CLOSING) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID), 0), 2) AS INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, GROSS_PROFIT, ROUND(100.0 * SALES_UNITS / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID), 0), 2) AS SALES_SHARE_PCT, ROUND(SALES_UNITS / NULLIF(SALES_UNITS + STORE_INV_UNITS_CLOSING, 0), 4) AS STR1, ROUND(SALES_UNITS / NULLIF((STORE_INV_UNITS_OPENING + STORE_INV_UNITS_CLOSING) / 2.0, 0), 4) AS STR2, ROUND(SALES_UNITS / NULLIF(STORE_INV_UNITS_OPENING, 0), 4) AS STR3 FROM UNIFIED_AGGREGATE ), TARGET_ALLOCATION_CALC AS ( SELECT C.*, COALESCE(HT.STORE_TARGET, HT_FALLBACK.STORE_TARGET) AS STORE_MONTHLY_TARGET, (C.SALES_REVENUE / NULLIF(C.SALES_UNITS, 0)) AS ASP, (C.INV_SHARE_PCT * (C.SALES_REVENUE / NULLIF(C.SALES_UNITS, 0))) AS RAW_TARGET_WEIGHT, (C.INV_SHARE_PCT * (C.SALES_REVENUE / NULLIF(C.SALES_UNITS, 0))) / NULLIF( SUM(C.INV_SHARE_PCT * (C.SALES_REVENUE / NULLIF(C.SALES_UNITS, 0))) OVER (PARTITION BY C.REPORT_MONTH, C.HIERARCHY_LEVEL, C.LOCATION_ID), 0 ) AS TARGET_WEIGHT_RATIO FROM CATEGORY_PERF C LEFT JOIN HIERARCHY_TARGETS HT ON C.HIERARCHY_LEVEL = HT.HIERARCHY_LEVEL AND C.LOCATION_ID = HT.LOCATION_ID AND C.REPORT_MONTH = HT.REPORT_MONTH LEFT JOIN ( SELECT HIERARCHY_LEVEL, LOCATION_ID, STORE_TARGET FROM HIERARCHY_TARGETS QUALIFY ROW_NUMBER() OVER (PARTITION BY HIERARCHY_LEVEL, LOCATION_ID ORDER BY REPORT_MONTH DESC) = 1 ) HT_FALLBACK ON C.HIERARCHY_LEVEL = HT_FALLBACK.HIERARCHY_LEVEL AND C.LOCATION_ID = HT_FALLBACK.LOCATION_ID ) SELECT REPORT_MONTH, MONTH_LABEL, HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, STORE_INV_UNITS_CLOSING, INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, SALES_SHARE_PCT, STORE_INV_UNITS_OPENING, STR1, STR2, STR3, ROUND(GROSS_PROFIT, 2) AS GROSS_PROFIT, STORE_MONTHLY_TARGET, ROUND(RAW_TARGET_WEIGHT, 4) AS RAW_TARGET_WEIGHT, ROUND(TARGET_WEIGHT_RATIO * 100.0, 4) AS WEIGHTED_CAT_TARGET_PCT, ROUND(STORE_MONTHLY_TARGET * TARGET_WEIGHT_RATIO, 2) AS CATEGORY_TARGET, ROUND(100.0 * SALES_REVENUE / NULLIF(STORE_MONTHLY_TARGET * TARGET_WEIGHT_RATIO, 0), 2) AS TARGET_PCT_ACHIEVED, CURRENT_TIMESTAMP() AS UPDATED_AT FROM TARGET_ALLOCATION_CALC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            